"""Recreate public portfolio charts from synthetic data generated by this project."""
from __future__ import annotations

import json
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

from src.forecast import run_demo


def generate_figures(output_dir: str | Path = "outputs") -> list[Path]:
    output = Path(output_dir)
    if not (output / "metrics.json").exists() or not (output / "synthetic_test_forecasts.csv").exists():
        run_demo(output)
    scores = json.loads((output / "metrics.json").read_text(encoding="utf-8"))
    data = pd.read_csv(output / "synthetic_test_forecasts.csv", parse_dates=["date"])
    figures = output / "figures"
    figures.mkdir(parents=True, exist_ok=True)
    saved = []

    # Figure 1: demand aggregated over all fictional store-item combinations.
    daily = data.groupby("date")[["units", "seasonal_naive", "gradient_boosting"]].sum()
    fig, ax = plt.subplots(figsize=(11, 5))
    daily.rename(columns={"units": "Observed (synthetic)", "seasonal_naive": "Seasonal naive",
                          "gradient_boosting": "Gradient boosting"}).plot(ax=ax)
    ax.set(title="Actual vs predicted demand — synthetic holdout",
           xlabel="Date", ylabel="Fictional units per day")
    ax.grid(alpha=0.2)
    fig.tight_layout()
    p = figures / "synthetic-forecast-lines.svg"
    fig.savefig(p)
    plt.close(fig)
    saved.append(p)

    # Figure 2: keep different units on separate axes.
    fig, axes = plt.subplots(nrows=1, ncols=3, figsize=(12, 4.5))
    for ax, (key, units) in zip(axes, [("MAE", "Units per series-day"),
                                      ("RMSE", "Units per series-day"),
                                      ("WAPE_pct", "Percent")]):
        values = [scores["seasonal_naive"][key], scores["gradient_boosting"][key]]
        bars = ax.bar(["Naive", "Boosting"], values)
        ax.bar_label(bars, labels=[f"{v:.3f}" for v in values], padding=3)
        ax.set(title=key.replace("_pct", ""), ylabel=units)
        ax.set_ylim(0, max(values) * 1.20)
    fig.suptitle("Forecast error comparison — synthetic holdout (lower is better)")
    fig.tight_layout()
    p = figures / "synthetic-error-metrics.svg"
    fig.savefig(p)
    plt.close(fig)
    saved.append(p)

    # Figure 3: WAPE by day of week on the held-out period.
    data["weekday"] = data["date"].dt.dayofweek
    errors = []
    for weekday in range(7):
        subset = data.loc[data["weekday"] == weekday]
        denominator = max(float(subset["units"].sum()), 1.0)
        errors.append([
            100 * float((subset["units"] - subset["seasonal_naive"]).abs().sum()) / denominator,
            100 * float((subset["units"] - subset["gradient_boosting"]).abs().sum()) / denominator,
        ])
    errors = np.asarray(errors)
    fig, ax = plt.subplots(figsize=(10, 5))
    positions = np.arange(7)
    ax.bar(positions - 0.18, errors[:, 0], width=0.36, label="Seasonal naive")
    ax.bar(positions + 0.18, errors[:, 1], width=0.36, label="Gradient boosting")
    ax.set(xticks=positions,
           xticklabels=["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
           ylabel="WAPE (%)", title="Error by day of week — synthetic holdout")
    ax.legend()
    fig.tight_layout()
    p = figures / "synthetic-weekday-error.svg"
    fig.savefig(p)
    plt.close(fig)
    saved.append(p)
    return saved


if __name__ == "__main__":
    for chart in generate_figures():
        print(chart)
